// ─────────────────────────────────────────────
// TRIGGER — Define e expõe os parâmetros globais
// da execução. Os nós de código leem daqui,
// eliminando hardcode nos algoritmos.
// ─────────────────────────────────────────────
return [
  {
    json: {
      ALPHA:      0.3,
      MAX_ITER:   1000,
      POP_SIZE:   20,
      CROSS_RATE: 0.8,
      MUT_RATE:   0.03
    }
  }
];

const params = $input.first().json;
const ALPHA    = params.ALPHA;
const MAX_ITER = params.MAX_ITER;
const N = 8;
function calcConflitos(state) {
  let c = 0;
  for (let i = 0; i < N - 1; i++)
    for (let j = i + 1; j < N; j++) {
      if (state[i] === state[j]) c++;
      if (Math.abs(state[i] - state[j]) === Math.abs(i - j)) c++;
    }
  return c;
}
function construirSolucao(alpha) {
  const s = new Array(N).fill(0);
  for (let col = 0; col < N; col++) {
    const candidatos = [];
    for (let linha = 0; linha < N; linha++) {
      const t = [...s]; t[col] = linha;
      candidatos.push({ linha, custo: calcConflitos(t) });
    }
    const cMin = Math.min(...candidatos.map(c => c.custo));
    const cMax = Math.max(...candidatos.map(c => c.custo));
    const limiar = cMin + alpha * (cMax - cMin);
    const rcl = candidatos.filter(c => c.custo <= limiar);
    s[col] = rcl[Math.floor(Math.random() * rcl.length)].linha;
  }
  return s;
}
function buscaLocal(estado) {
  let atual = [...estado];
  let hAtual = calcConflitos(atual);
  let melhorou = true;
  while (melhorou && hAtual > 0) {
    melhorou = false;
    let melhorH = hAtual, melhorMov = null;
    for (let col = 0; col < N; col++)
      for (let linha = 0; linha < N; linha++) {
        if (linha === atual[col]) continue;
        const viz = [...atual]; viz[col] = linha;
        const hv = calcConflitos(viz);
        if (hv < melhorH) { melhorH = hv; melhorMov = { col, linha }; }
      }
    if (melhorMov) { atual[melhorMov.col] = melhorMov.linha; hAtual = melhorH; melhorou = true; }
  }
  return { estado: atual, h: hAtual };
}
const resultados = [];
for (let rodada = 1; rodada <= 50; rodada++) {
  const t0 = Date.now();
  let melhorSolucao = null, melhorH = Infinity;
    let iters = 0;
  for (let it = 0; it < MAX_ITER; it++) {
    iters = it + 1;
    const { estado, h } = buscaLocal(construirSolucao(ALPHA));
    if (h < melhorH) { melhorH = h; melhorSolucao = [...estado]; }
    if (melhorH === 0) break;
  }
  resultados.push({ json: {
    Rodada: rodada,
    Algoritmo: 'GRASP',
    Tempo_ms: Date.now() - t0,
    Iteracoes_Geracoes: iters,
    Melhor_Solucao: JSON.stringify(melhorSolucao),
    Fitness_Final_h: melhorH,
    Sucesso: melhorH === 0 ? 'SIM' : 'NAO'
  }});
}
return resultados;

const params    = $input.first().json;
const POP_SIZE  = params.POP_SIZE;
const TX_CRUZ   = params.CROSS_RATE;
const TX_MUT    = params.MUT_RATE;
const MAX_GER   = params.MAX_ITER;
const N         = 8;
const BPR       = 3;
const TOTAL_BITS = N * BPR;
const N_ELITE   = 2;

function decodificar(cromo) {
  const s = [];
  for (let i = 0; i < N; i++) {
    const b = cromo.slice(i * BPR, i * BPR + BPR);
    s.push(b[0] * 4 + b[1] * 2 + b[2]);
  }
  return s;
}

function calcConflitos(state) {
  let c = 0;
  for (let i = 0; i < N - 1; i++)
    for (let j = i + 1; j < N; j++) {
      if (state[i] === state[j]) c++;
      if (Math.abs(state[i] - state[j]) === Math.abs(i - j)) c++;
    }
  return c;
}

function calcFitness(cromo) {
  const h = calcConflitos(decodificar(cromo));
  return { f: 1 / (1 + h), h };
}

function gerarCromo() {
  return Array.from({ length: TOTAL_BITS }, () => (Math.random() < 0.5 ? 1 : 0));
}

function roleta(pop, fits) {
  const total = fits.reduce((a, b) => a + b, 0);
  let r = Math.random() * total;
  for (let i = 0; i < pop.length; i++) { r -= fits[i]; if (r <= 0) return [...pop[i]]; }
  return [...pop[pop.length - 1]];
}

function cruzar(p1, p2) {
  if (Math.random() > TX_CRUZ) return [[...p1], [...p2]];
  const k = 1 + Math.floor(Math.random() * (TOTAL_BITS - 1));
  return [[...p1.slice(0, k), ...p2.slice(k)], [...p2.slice(0, k), ...p1.slice(k)]];
}

function mutar(cromo) {
  return cromo.map(b => (Math.random() < TX_MUT ? 1 - b : b));
}

const resultados = [];
for (let rodada = 1; rodada <= 50; rodada++) {
  let pop = Array.from({ length: POP_SIZE }, gerarCromo);
  const t0 = Date.now();
  let melhorCromo = null, melhorH = Infinity, geracoes = 0;

  for (let g = 0; g < MAX_GER; g++) {
    geracoes = g + 1;
    const avs = pop.map(c => calcFitness(c));
    const fits = avs.map(a => a.f);

    for (let i = 0; i < POP_SIZE; i++)
      if (avs[i].h < melhorH) { melhorH = avs[i].h; melhorCromo = [...pop[i]]; }
    if (melhorH === 0) break;

    const idxOrdenados = fits
      .map((f, i) => ({ f, i }))
      .sort((a, b) => b.f - a.f);
    const elites = idxOrdenados.slice(0, N_ELITE).map(e => [...pop[e.i]]);

    const nova = [];
    while (nova.length < POP_SIZE) {
      const [f1, f2] = cruzar(roleta(pop, fits), roleta(pop, fits));
      nova.push(mutar(f1));
      if (nova.length < POP_SIZE) nova.push(mutar(f2));
    }

    const fitNova = nova.map(c => calcFitness(c).f);
    const idxNovaPiores = fitNova
      .map((f, i) => ({ f, i }))
      .sort((a, b) => a.f - b.f)
      .slice(0, N_ELITE)
      .map(e => e.i);
    for (let k = 0; k < N_ELITE; k++) nova[idxNovaPiores[k]] = elites[k];

    pop = nova;
  }

  const estadoFinal = melhorCromo ? decodificar(melhorCromo) : new Array(N).fill(0);
  resultados.push({ json: {
    Rodada: rodada,
    Algoritmo: 'Algoritmo Genetico',
    Tempo_ms: Date.now() - t0,
    Iteracoes_Geracoes: geracoes,
    Melhor_Solucao: JSON.stringify(estadoFinal),
    Conflitos_Finais_CQ: melhorH,
    Sucesso: melhorH === 0 ? 'SIM' : 'NAO'
  }});
}
return resultados;

const todos = $input.first().json.todos;
const grasp = todos.filter(r => r.Algoritmo === 'GRASP');
const ag    = todos.filter(r => r.Algoritmo === 'Algoritmo Genetico');

function stats(arr, campo) {
  const vals = arr.map(r => Number(r[campo]));
  const n = vals.length;
  if (n === 0) return { media: 0, desvio: 0 };
  const media = vals.reduce((a, b) => a + b, 0) / n;
  const desvio = Math.sqrt(vals.reduce((a, b) => a + Math.pow(b - media, 2), 0) / n);
  return { media: +media.toFixed(2), desvio: +desvio.toFixed(2) };
}

function taxaSucesso(arr) {
  if (arr.length === 0) return 0;
  return +((arr.filter(r => r.Sucesso === 'SIM').length / arr.length) * 100).toFixed(1);
}

function top5Solucoes(arr) {
  return arr
    .slice()
    .sort((a, b) => Number(a.Conflitos_Finais_CQ) - Number(b.Conflitos_Finais_CQ))
    .map(r => r.Melhor_Solucao)
    .filter((v, i, a) => a.indexOf(v) === i)
    .slice(0, 5)
    .join(' | ');
}

return [
  { json: {
    Algoritmo:          'GRASP',
    Execucoes:          grasp.length,
    Media_Tempo_ms:     stats(grasp, 'Tempo_ms').media,
    Desvio_Tempo_ms:    stats(grasp, 'Tempo_ms').desvio,
    Media_Iteracoes:    stats(grasp, 'Iteracoes_Geracoes').media,
    Desvio_Iteracoes:   stats(grasp, 'Iteracoes_Geracoes').desvio,
    Taxa_Sucesso_pct:   taxaSucesso(grasp),
    Media_Conflitos_CQ: stats(grasp, 'Conflitos_Finais_CQ').media,
    Top5_Solucoes:      top5Solucoes(grasp)
  }},
  { json: {
    Algoritmo:          'Algoritmo Genetico',
    Execucoes:          ag.length,
    Media_Tempo_ms:     stats(ag, 'Tempo_ms').media,
    Desvio_Tempo_ms:    stats(ag, 'Tempo_ms').desvio,
    Media_Iteracoes:    stats(ag, 'Iteracoes_Geracoes').media,
    Desvio_Iteracoes:   stats(ag, 'Iteracoes_Geracoes').desvio,
    Taxa_Sucesso_pct:   taxaSucesso(ag),
    Media_Conflitos_CQ: stats(ag, 'Conflitos_Finais_CQ').media,
    Top5_Solucoes:      top5Solucoes(ag)
  }}
];
